import json
from pathlib import Path
root=Path(__file__).parent
x=json.loads((root/'candidate-the-aeneid-modern-en.json').read_text())
ledger=json.loads((root/'ENGLISH-REPAIRS.json').read_text())
def fix(b,p,before,after,reason):
 t=x['chapters'][b-1]['paragraphs'][p-1]
 assert before in t,(b,p,before)
 x['chapters'][b-1]['paragraphs'][p-1]=t.replace(before,after)
 ledger.append(dict(book=b,paragraph=p,before=before,after=after,reason=reason))
fix(9,55,'Plunged in the flood, he made the waters fly.','At last he leaped into the river in full armor, scattering the water.','IX.815–18 restores missing subject and deliberate leap, also missing in the raw Dryden witness.')
fix(10,9,"the two bold brothers of Sarpedon's blood, Asius and Acmon; both Assaraci; young Haemon, and, though young, resolved to die. With these were joined Clarus and Thymoetes; Tibris and Castor, both of Lycian kind.","Asius, son of Imbrasus, and Thymoetes, son of Hicetaon; the two men named Assaracus; the older Thymbris and Castor. With them stood Sarpedon's two brothers, and Clarus and Thaemon from the Lycian highlands.",'X.123–26 corrects parentage and catalogue conflations.')
fix(10,15,'from Asium and Cosa','from Clusium and Cosa','X.167 Clusi, Clusium, not Asium.')
fix(10,22,'fierce tigers, reined and curbed','two lions, reined and curbed','X.253 biiugique ad frena leones.')
fix(10,28,'the newly raised and raw clowns','the newly raised, inexperienced farmers','Modern sense of clowns misrepresents agrestis and historical rural sense.')
fix(10,28,'who, not like others born, was ripped and torn from his wretched mother; sacred, O Phoebus, to you from his birth, for his beginning life was free from biting steel.','who had been cut from his mother after her death and dedicated to you, Phoebus. What good had it done him to escape death by steel as an infant?','X.315–17 exsectum iam matre perempta; restores mother’s death and rhetorical question.')
fix(10,28,'and sought polluted joys with obscene lust; the Trojan sword would have cured his love of boys, had not his seven bold brethren stopped the course of the fierce champion, with united force.','his latest love; the Trojan sword would have ended his lifelong love of young men, had not seven brothers, sons of Phorcus, stood together to block the fierce champion.','X.324–29 distinguishes Phorcus’ sons from Cydon’s brothers and removes a moral condemnation added by Dryden to the Latin narrator.')
fix(10,29,'pierced his right arm, and holding on, bereft him of the use of both, and pinioned down his left.','passed through his right arm and flew on, bloody, along its original course. The dying arm hung from his shoulder by its tendons.','X.338–42 no left-arm pinioning, severed right arm remains attached by sinews.')
fix(10,35,'Jove is impartial, and to both the same.','My father can accept either outcome.','X.450 sorti pater aequus utrique est refers to Evander accepting victory or an honorable death, not Jupiter’s neutrality.')
fix(10,38,"Eurytion's artful hands","the skillful hands of Clonus, son of Eurytus,",'X.499 Clonus Eurytides; distinct craftsman.')
fix(10,56,"Then brave Messapus slew Ericetes, who drew his lineage from Lycaon's blood. But Ericetes found his fate from his headstrong horse, who threw his master, as he made a bound: the chief, alighting, stuck him to the ground. Then Clonius, hand to hand, on foot assails; the Trojan sinks, and Neptune's son prevails.","Then Messapus killed Cronius, who lay on the ground after a fall from his unruly horse, and Erichaetes, son of Lycaon, who fought on foot.",'X.749–52 restores names and correct association of horse fall.')
fix(10,56,'the great Antronius','Thronius','X.753 Thronium.')
fix(10,57,'infernal Ate','pale Tisiphone','X.761 pallida Tisiphone, not Ate.')
fix(10,58,'or like a mountain ash, whose roots are spread, deep fixed in earth, while in clouds he hides his head.','or like Orion carrying an ancient ash tree down from the mountain peaks, walking on the earth with his head hidden among the clouds.','X.766–67 Orion carries ash tree, not compared with rooted tree.')
fix(11,34,'well-boiled oak','fire-hardened oak','XI.553 robore cocto, hardened by heat, not boiled.')
fix(11,40,'Astonished Aunus just arrives','The astonished son of Aunus just arrives','XI.699–700 Appenninicolae ... filius Auni, father and son distinct.')
fix(11,43,'through unsinged flames we march','we walk unsinged through the flames','English misplaced modifier made the flames unsinged rather than the worshippers.')
fix(12,34,'Then he slew Dares, Butes, and Sybaris, whom his stumbling horse had thrown over its neck.','With a spear he sent Asbytes to join Eumedes in death. He killed Chloreus, Sybaris, Dares, Thersilochus, and Thymoetes, whom his unruly horse had thrown over its neck.','XII.362–64 restores named fighters and correct victim of horse fall.')
fix(12,47,'Cethegus, Tanais, and Tagus','Cethegus, Tanais, and Talos','XII.513 Talon, distinct from Tagus.')
fix(12,51,'Nor, Cisseus, could you escape Turnus\'s hand, though you were the strongest of the Arcadian band.','Nor could your right hand save you from Turnus, Cretheus, bravest of the Greeks.','XII.538 Cretheu ... Graium fortissime.')
fix(12,52,'Iolas fell','Aeolus fell','XII.542 Aeole; wrong personal name in Dryden.')
fix(12,73,'In heaven they were called the Dirae,','Two of the sisters were called the Dirae; the third was Megaera of Tartarus. The Dirae','XII.845–47 distinguishes pair of Dirae from their sister Megaera.')
(root/'candidate-the-aeneid-modern-en.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
(root/'ENGLISH-REPAIRS.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
print('English repair entries',len(ledger))
